        var t = "" + (i.title || "");
        var orig = t;
        t = t.replace(/\[(?![^\]]*[话話章回卷季幕])[^\]]*\]/g, "");
        if (sn) {
            t = t.split(sn).join("");
        }
        t = t.replace(/\s+/g, " ").trim();
        if (!t) t = orig;
        return JSON.stringify({
            title: t,
            aid: i.aid
        });
    });
})()

